From 6fc94bb6442df44bc8a61cf2317afa3a312b668e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Fri, 20 Nov 2026 23:40:45 +0100
Subject: [PATCH] handlebuttonevents: don't retry the lid action when sleep
 failed

logind also reports a resume when a sleep attempt fails, so with the lid
closed a failing suspend or hibernate was retried every 10-20 s until
the battery ran out. Now it is only re-triggered after a real sleep.

BUG: 528651
---
 daemon/actions/bundled/handlebuttonevents.cpp |  7 +++++
 daemon/controllers/suspendcontroller.cpp      | 29 +++++++++++++++++++
 daemon/controllers/suspendcontroller.h        | 12 ++++++++
 3 files changed, 48 insertions(+)

diff --git a/daemon/actions/bundled/handlebuttonevents.cpp b/daemon/actions/bundled/handlebuttonevents.cpp
index 5d8a9e753..0eb39cbe6 100644
--- a/daemon/actions/bundled/handlebuttonevents.cpp
+++ b/daemon/actions/bundled/handlebuttonevents.cpp
@@ -273,6 +273,13 @@ void HandleButtonEvents::checkOutputs()

 void HandleButtonEvents::onResumeFromSuspend()
 {
+    if (!core()->suspendController()->lastSleepSucceeded()) {
+        // The sleep attempt failed, so this isn't a wakeup. Triggering the lid action again would most
+        // likely fail the same way, over and over for as long as the lid stays closed.
+        qCDebug(POWERDEVIL) << "HandleButtonEvents: the system did not sleep, not re-triggering the lid action";
+        return;
+    }
+
     // We start with type of resume, if we find we don't like we ask it to suspend directly.
     const auto wakeupType = core()->suspendController()->lastWakeupType();
     if (wakeupType & SuspendController::WakeupSource::Network || wakeupType & SuspendController::WakeupSource::Telephony
diff --git a/daemon/controllers/suspendcontroller.cpp b/daemon/controllers/suspendcontroller.cpp
index f583cff6c..d08817ce9 100644
--- a/daemon/controllers/suspendcontroller.cpp
+++ b/daemon/controllers/suspendcontroller.cpp
@@ -20,6 +20,8 @@
 #include <QDir>
 #include <QFile>

+#include <time.h>
+
 using namespace Qt::StringLiterals;

 inline constexpr QLatin1StringView LOGIN1_SERVICE("org.freedesktop.login1");
@@ -27,6 +29,19 @@ inline constexpr QLatin1StringView CONSOLEKIT2_SERVICE("org.freedesktop.ConsoleK

 inline static const QLatin1String s_wakeupSysFsPath("/sys/class/wakeup");

+#ifdef Q_OS_LINUX
+// Total time the system has spent suspended since boot: CLOCK_BOOTTIME keeps counting while
+// the system sleeps, CLOCK_MONOTONIC does not.
+static std::chrono::nanoseconds timeSuspendedSinceBoot()
+{
+    timespec boottime;
+    timespec monotonic;
+    clock_gettime(CLOCK_BOOTTIME, &boottime);
+    clock_gettime(CLOCK_MONOTONIC, &monotonic);
+    return std::chrono::seconds(boottime.tv_sec - monotonic.tv_sec) + std::chrono::nanoseconds(boottime.tv_nsec - monotonic.tv_nsec);
+}
+#endif
+
 SuspendController::SuspendController()
     : QObject()
 {
@@ -109,6 +124,15 @@ void SuspendController::slotLogin1PrepareForSleep(bool active)
 {
 #ifdef Q_OS_LINUX
     snapshotWakeupCounts(active);
+
+    if (active) {
+        m_timeSuspendedBeforeSleep = timeSuspendedSinceBoot();
+    } else {
+        // the two clocks are read one after the other, so allow for a tiny difference
+        using namespace std::chrono_literals;
+        m_lastSleepSucceeded = timeSuspendedSinceBoot() - m_timeSuspendedBeforeSleep > 1ms;
+        qCDebug(POWERDEVIL) << "Resumed, system actually slept:" << m_lastSleepSucceeded;
+    }
 #endif

     if (active) {
@@ -189,4 +213,9 @@ QStringList SuspendController::wakeupDevices()
     return m_lastWakeupSources;
 }

+bool SuspendController::lastSleepSucceeded() const
+{
+    return m_lastSleepSucceeded;
+}
+
 #include "moc_suspendcontroller.cpp"
diff --git a/daemon/controllers/suspendcontroller.h b/daemon/controllers/suspendcontroller.h
index f63b8517a..04a4b72d3 100644
--- a/daemon/controllers/suspendcontroller.h
+++ b/daemon/controllers/suspendcontroller.h
@@ -17,6 +17,8 @@

 #include <KJob>

+#include <chrono>
+
 #include <sessionmanagement.h>

 #include "powerdevilcore_export.h"
@@ -57,6 +59,12 @@ public:
     WakeupSources lastWakeupType();
     QStringList wakeupDevices();

+    /**
+     * Whether the system actually slept before the last resumeFromSuspend() signal.
+     * logind also sends that signal when an attempt to sleep failed, in which case this returns false.
+     */
+    bool lastSleepSucceeded() const;
+
 Q_SIGNALS:
     /**
      * This signal is emitted when the PC is resuming from suspension
@@ -82,6 +90,10 @@ private:
 #endif
     QHash<QString, int> m_wakeupCounts;
     QStringList m_lastWakeupSources;
+#ifdef Q_OS_LINUX
+    std::chrono::nanoseconds m_timeSuspendedBeforeSleep{0};
+#endif
+    bool m_lastSleepSucceeded = true;
     UdevQt::Client *m_udevClient;
 };

